<template><div class="page"><div class="section-title"><div><h2>日常工单</h2><span class="muted">创建与 Agent 对话式生成运维方案</span></div><n-button type="primary" @click="show=true">新建工单</n-button></div><div class="panel"><n-data-table :columns="columns" :data="items"/></div><n-modal v-model:show="show"><n-card title="新建日常工单" style="width:520px"><n-form><n-form-item label="类型"><n-select v-model:value="form.type" :options="types"/></n-form-item><n-form-item label="标题"><n-input v-model:value="form.title"/></n-form-item><n-form-item label="Namespace"><n-input v-model:value="form.namespace"/></n-form-item><n-form-item label="目标"><n-input v-model:value="form.target"/></n-form-item><n-form-item label="需求描述"><n-input v-model:value="form.description" type="textarea"/></n-form-item></n-form><template #footer><n-button @click="show=false">取消</n-button><n-button type="primary" @click="create">创建</n-button></template></n-card></n-modal></div></template>
<script setup>import {ref,onMounted} from 'vue';import {useRouter} from 'vue-router';import {workOrderApi} from '@/api';const router=useRouter(),show=ref(false),items=ref([]),form=ref({type:'deployment-plan',title:'',namespace:'autoops-test',target:'',description:''}),types=['package-generation','config-generation','deployment-plan','cluster-check','operation-script'].map(x=>({label:x,value:x}));const columns=[{title:'标题',key:'title'},{title:'类型',key:'type'},{title:'目标',key:'target'},{title:'状态',key:'status'},{title:'创建时间',key:'created_at',render:r=>new Date(r.created_at).toLocaleString()}];async function load(){items.value=(await workOrderApi.list()).work_orders||[]}async function create(){const created=await workOrderApi.create(form.value);show.value=false;router.push(`/app/work-orders/${created.id}`);form.value={type:'deployment-plan',title:'',namespace:'autoops-test',target:'',description:''};await load()}onMounted(load)</script>
